import{_ as n,o as a,c as i,a0 as o}from"./chunks/framework.DhQjJcnt.js";const u=JSON.parse('{"title":"Skill: /openapi","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/openapi.md","filePath":"references/skills/openapi.md"}'),c={name:"references/skills/openapi.md"};function t(l,e,d,r,p,s){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-openapi" tabindex="-1">Skill: <code>/openapi</code> <a class="header-anchor" href="#skill-openapi" aria-label="Permalink to &quot;Skill: `/openapi`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>openapi</code> (Tích hợp CLI <code>flowgrid openapi_render</code>, <code>openapi_build_ui</code>)</p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/openapi</code></li><li>Dùng qua CLI để sinh từng file riêng lẻ: <code>flowgrid openapi_gen --spec surfaces/.../api/&lt;seq&gt;/01-backend-spec.yaml</code></li><li>Dùng qua CLI để quét và sinh toàn bộ: <code>flowgrid openapi_gen</code></li><li>Render và gộp API: <code>flowgrid openapi_render</code></li><li>Build UI tĩnh: <code>flowgrid openapi_build_ui</code></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc file hợp đồng Backend: <code>01-backend-spec.yaml</code>.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Sinh ra file <code>02-openapi.yaml</code> (nằm cùng cấp thư mục với file 01).</li><li>Sau khi chạy <code>flowgrid openapi_render</code>, toàn bộ các file <code>02-openapi.yaml</code> từ các module sẽ được tổng hợp thành một file OpenAPI thống nhất tại <code>docs/openapi/api.yaml</code>.</li><li>(Tùy chọn) Chạy <code>flowgrid openapi_build_ui</code> sẽ sinh ra thư mục chứa giao diện Swagger/Redocly UI tĩnh.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Chuyên dùng để chuyển đổi (Transform) chuẩn nội bộ <code>01-backend-spec.yaml</code> sang chuẩn quốc tế <strong>OpenAPI 3.0.3</strong> (<code>02-openapi.yaml</code>).</li><li>OpenAPI trong FlowGrid hoàn toàn là một <strong>Tài liệu (Docs artifact)</strong>, không phải là công cụ sinh code (bộ code). Việc sinh mã nguồn Backend từ API Contract sẽ do các lệnh riêng biệt (như <code>flowgrid api-gen</code>) của BE xử lý.</li><li>Tuyệt đối không dùng các thư viện sinh OpenAPI từ source code (như <code>nestjs --openapi</code>) để ghi đè vào Docs Hub. Quy trình ở đây là: Docs (Hợp đồng) sinh ra OpenAPI, chứ không phải Code sinh ra OpenAPI.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li><strong>Trước đó:</strong> Nhận đầu vào từ kết quả của <code>/api-spec</code> (hoặc <code>/api-update</code>, <code>/api-integration</code>).</li><li><strong>Sau đó:</strong> Dữ liệu Swagger sẽ được tích hợp thẳng vào trang Docs VitePress qua lệnh render.</li></ul><h2 id="chu-y-quan-trong" tabindex="-1">Chú ý quan trọng <a class="header-anchor" href="#chu-y-quan-trong" aria-label="Permalink to &quot;Chú ý quan trọng&quot;">​</a></h2><ul><li>Nếu file OpenAPI sinh ra bị thiếu thông tin (ví dụ: thiếu schema <code>$refs</code>, thiếu examples), <strong>tuyệt đối không</strong> được sửa trực tiếp file <code>02-openapi.yaml</code>. Tác nhân (Agent) phải sửa tận gốc ở file <code>01-backend-spec.yaml</code> rồi chạy lệnh gen lại.</li><li>Dùng cờ <code>--dry-run</code> để test thử hoặc <code>--force</code> để ép ghi đè nếu cần thiết.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/openapi</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',20)])])}const g=n(c,[["render",t]]);export{u as __pageData,g as default};
